        return int(max(n))

#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minPartitions(string n) {
        char mx = '0';
        for (char c : n) {
            if (c > mx) mx = c;
        }
        return mx - '0';
    }
};

class Solution {
    public int minPartitions(String n) {
        int maxD = 0;
        for (int i = 0; i < n.length(); ++i) {
            int d = n.charAt(i) - '0';
            if (d > maxD) maxD = d;
        }
        return maxD;
    }
}

/**
 * @param {string} n
 * @return {number}
 */
var minPartitions = function(n) {
    let maxD = 0;
    for (let i = 0; i < n.length; ++i) {
        const d = Number(n[i]);
        if (d > maxD) maxD = d;
    }
    return maxD;
};
